import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr02116Controller {
  @Post('/retirement-pays')
  @HttpCode(200)
  async createRetirementPay(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const employeeId = Number(data['employeeId']);
    if (data['employeeId'] === undefined || data['employeeId'] === null || data['employeeId'] === '' || !Number.isInteger(employeeId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '퇴직 임직원을 확인해 주세요.');
    }
    const retirementDate = data['retirementDate'];
    if (typeof retirementDate !== 'string' || !DATE_PATTERN.test(retirementDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '퇴직일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '대상 임직원을 찾을 수 없습니다.');
      }
      // 가정: 적용 시작일이 퇴직일 이전인 최신 퇴직기준을 적용한다.
      const criteria = await db.query(
        'SELECT retirement_criteria_id AS "retirementCriteriaId" FROM retirement_criteria '
          + 'WHERE start_date <= CAST(:retirementDate AS date) '
          + 'ORDER BY start_date DESC, retirement_criteria_id DESC LIMIT 1',
        { retirementDate },
      );
      if (criteria.length === 0) {
        throw new ApiError(422, 'RETIREMENT_CRITERIA_NOT_FOUND', '퇴직기준이 설정되어 있지 않습니다. 퇴직기준을 먼저 설정해 주세요.');
      }
      const duplicated = await db.query(
        'SELECT retirement_pay_id FROM retirement_pay '
          + 'WHERE employee_id = CAST(:employeeId AS bigint) AND retirement_date = CAST(:retirementDate AS date)',
        { employeeId, retirementDate },
      );
      if (duplicated.length > 0) {
        throw new ApiError(409, 'INVALID_STATE', '이미 산정된 퇴직금이 있습니다.');
      }
      // 가정: 확정 여부 초기값은 false.
      // TODO: 산정액·원천징수세액 계산 입력(급여·근속 데이터)이 스펙에 없어 NULL로 저장한다.
      const rows = await db.query(
        'INSERT INTO retirement_pay (employee_id, retirement_criteria_id, retirement_date, confirmed, created_at, updated_at) '
          + 'VALUES (CAST(:employeeId AS bigint), CAST(:criteriaId AS bigint), CAST(:retirementDate AS date), false, now(), now()) '
          + 'RETURNING retirement_pay_id AS "retirementPayId", calculated_amount AS "calculatedAmount", withholding_tax AS "withholdingTax"',
        { employeeId, criteriaId: criteria[0].retirementCriteriaId, retirementDate },
      );
      const row = rows[0];
      return {
        retirementPayId: Number(row.retirementPayId),
        calculatedAmount: row.calculatedAmount === null ? null : Number(row.calculatedAmount),
        withholdingTax: row.withholdingTax === null ? null : Number(row.withholdingTax),
      };
    });
  }

  @Get('/retirement-pays')
  async listRetirementPays(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    let size = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기가 올바르지 않습니다.');
    }
    if (size > 200) {
      size = 200;
    }
    const conditions: string[] = [];
    const params: Record<string, unknown> = { size, offset: page * size };
    if (query['employeeId'] !== undefined && query['employeeId'] !== '') {
      const employeeId = Number(query['employeeId']);
      if (!Number.isInteger(employeeId)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '퇴직 임직원을 확인해 주세요.');
      }
      conditions.push('employee_id = CAST(:employeeId AS bigint)');
      params['employeeId'] = employeeId;
    }
    if (query['retirementDate'] !== undefined && query['retirementDate'] !== '') {
      const d = query['retirementDate'];
      if (typeof d !== 'string' || !DATE_PATTERN.test(d)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '퇴직일을 YYYY-MM-DD 형식으로 입력해 주세요.');
      }
      conditions.push('retirement_date = CAST(:retirementDate AS date)');
      params['retirementDate'] = d;
    }
    if (query['confirmed'] !== undefined && query['confirmed'] !== '') {
      const c = String(query['confirmed']);
      if (c !== 'true' && c !== 'false') {
        throw new ApiError(400, 'VALIDATION_FAILED', '확정 여부 값이 올바르지 않습니다.');
      }
      conditions.push('confirmed = (:confirmed = \'true\')');
      params['confirmed'] = c;
    }
    const where = conditions.length > 0 ? ' WHERE ' + conditions.join(' AND ') : '';
    return transaction(async (db) => {
      const countRows = await db.query('SELECT COUNT(*) AS total FROM retirement_pay' + where, params);
      const rows = await db.query(
        'SELECT retirement_pay_id AS "retirementPayId", employee_id AS "employeeId", '
          + 'retirement_date AS "retirementDate", calculated_amount AS "calculatedAmount", confirmed AS "confirmed" '
          + 'FROM retirement_pay' + where
          + ' ORDER BY retirement_date DESC, retirement_pay_id DESC LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        params,
      );
      return {
        items: rows.map((r: any) => ({
          retirementPayId: Number(r.retirementPayId),
          employeeId: Number(r.employeeId),
          retirementDate: r.retirementDate,
          calculatedAmount: r.calculatedAmount === null ? null : Number(r.calculatedAmount),
          confirmed: r.confirmed,
        })),
        page,
        size,
        total: Number(countRows[0].total),
      };
    });
  }

  @Get('/retirement-pays/estimate')
  async getRetirementPayEstimate(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const raw = query['estimateDate'];
    const hasDate = raw !== undefined && raw !== '';
    if (hasDate && (typeof raw !== 'string' || !DATE_PATTERN.test(raw))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '추계 기준일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const criteria = await db.query(
        'SELECT retirement_criteria_id FROM retirement_criteria '
          + 'WHERE start_date <= COALESCE(CAST(:estimateDate AS date), CAST(now() AS date)) LIMIT 1',
        { estimateDate: hasDate ? raw : null },
      );
      if (criteria.length === 0) {
        throw new ApiError(422, 'RETIREMENT_CRITERIA_NOT_FOUND', '퇴직기준이 설정되어 있지 않습니다. 퇴직기준을 먼저 설정해 주세요.');
      }
      // 가정: 급여 데이터가 스펙에 없어, 기준일까지 산정된 퇴직금 산정액의 합계를 추계액으로 돌려준다.
      // TODO: 재직자 급여·근속 기반 추계 산식은 입력에 없어 구현하지 못했다.
      const rows = await db.query(
        'SELECT COALESCE(SUM(calculated_amount), 0) AS "estimatedAmount" FROM retirement_pay '
          + 'WHERE retirement_date <= COALESCE(CAST(:estimateDate AS date), CAST(now() AS date))',
        { estimateDate: hasDate ? raw : null },
      );
      return { estimatedAmount: Number(rows[0].estimatedAmount) };
    });
  }
}

