import { useState } from 'react';
import {
  call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer,
  Form, Field, DateInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr02116Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [retirementDate, setRetirementDate] = useState('');
  const [confirmed, setConfirmed] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [creating, setCreating] = useState(false);
  const [newEmployeeId, setNewEmployeeId] = useState<number | string>('');
  const [newDate, setNewDate] = useState('');
  const [estimateDate, setEstimateDate] = useState('');
  const [estimate, setEstimate] = useState<unknown>(undefined);
  const [estimateError, setEstimateError] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/retirement-pays', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo, role],
  );

  const search = () => {
    setPageNo(0);
    setApplied({ employeeId, retirementDate, confirmed });
  };

  const reset = () => {
    setEmployeeId('');
    setRetirementDate('');
    setConfirmed('');
    setPageNo(0);
    setApplied({});
  };

  const create = async () => {
    if (newEmployeeId === '' || !newDate) {
      throw new Error('퇴직 임직원과 퇴직일을 입력해 주세요.');
    }
    await call('POST', '/retirement-pays', role, { employeeId: newEmployeeId, retirementDate: newDate });
    notify('퇴직금을 산정했습니다.');
    setCreating(false);
    setNewEmployeeId('');
    setNewDate('');
    list.reload();
  };

  const loadEstimate = async () => {
    setEstimateError('');
    try {
      const res = await call('GET', '/retirement-pays/estimate', role, undefined, { estimateDate });
      setEstimate(res['estimatedAmount']);
    } catch (e) {
      setEstimate(undefined);
      setEstimateError(e instanceof Error ? e.message : '추계액을 불러오지 못했습니다.');
    }
  };

  const data = list.data;

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>퇴직금 산정 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="퇴직 임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
          <Field label="퇴직일">
            <DateInput value={retirementDate} onChange={setRetirementDate} />
          </Field>
          <Field label="확정 여부">
            <Select
              value={confirmed}
              onChange={setConfirmed}
              options={[['true', '확정'], ['false', '미확정']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type="button" onClick={() => setCreating(true)}>퇴직금 산정</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={data?.items ?? []}
          empty="산정된 퇴직금이 없습니다."
          columns={[
            { key: 'retirementPayId', label: '퇴직금 ID' },
            { key: 'employeeId', label: '퇴직 임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'retirementDate', label: '퇴직일', render: (r) => <DateText value={r.retirementDate} /> },
            { key: 'calculatedAmount', label: '퇴직금 산정액', render: (r) => <Num value={r.calculatedAmount} /> },
            { key: 'confirmed', label: '확정 여부', render: (r) => <Badge value={r.confirmed ? '확정' : '미확정'} /> },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      <section className="box span-4">
        <h2>퇴직금 추계액</h2>
        <Field label="추계 기준일">
          <DateInput value={estimateDate} onChange={setEstimateDate} />
        </Field>
        <button type="button" onClick={loadEstimate}>추계액 조회</button>
        {estimateError ? <ErrorText text={estimateError} /> : null}
        {estimate !== undefined ? (
          <p>기준일 퇴직금 추계액: <Num value={estimate} /></p>
        ) : null}
      </section>
      {creating ? (
        <Drawer title="퇴직금 산정" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="산정">
            <Field label="퇴직 임직원" required>
              <LookupSelect table="employee" role={role} value={newEmployeeId} onChange={setNewEmployeeId} />
            </Field>
            <Field label="퇴직일" required>
              <DateInput value={newDate} onChange={setNewDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
